package com.cinebooking.commerce;
import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; import static com.cinebooking.commerce.CommerceDtos.*;
@RestController @RequestMapping("/api/admin/commerce")
public class AdminCommerceController { private final CommerceService s; public AdminCommerceController(CommerceService s){this.s=s;} @GetMapping("/products") public List<ProductResponse> products(){return s.allProducts();} @PostMapping("/products") public ProductResponse create(@Valid @RequestBody ProductRequest r){return s.saveProduct(null,r);} @PutMapping("/products/{id}") public ProductResponse update(@PathVariable UUID id,@Valid @RequestBody ProductRequest r){return s.saveProduct(id,r);} @DeleteMapping("/products/{id}") public void delete(@PathVariable UUID id){s.deleteProduct(id);} @GetMapping("/vouchers") public List<VoucherResponse> vouchers(){return s.allVouchers();} @PostMapping("/vouchers") public VoucherResponse createVoucher(@Valid @RequestBody VoucherRequest r){return s.saveVoucher(null,r);} @PutMapping("/vouchers/{id}") public VoucherResponse updateVoucher(@PathVariable UUID id,@Valid @RequestBody VoucherRequest r){return s.saveVoucher(id,r);} @DeleteMapping("/vouchers/{id}") public void deleteVoucher(@PathVariable UUID id){s.deleteVoucher(id);} }
